#!/usr/bin/env bash
set -euo pipefail
[[ "${1:-}" == --source-context && -n "${2:-}" && "${3:-}" == --kind && "${4:-}" =~ ^(sbom|trivy)$ && "${5:-}" == --release-manifest && -n "${6:-}" && $# == 6 ]] || { echo 'Usage: run-internal-ci-image-scan.sh --source-context <context> --kind <sbom|trivy> --release-manifest <manifest>' >&2; exit 64; }
context=$2; kind=$4; manifest=$6; workspace=$PWD; artifact_root="$workspace/.release/internal-ci/${CI_COMMIT_SHA:?}"; source_root="${RUNNER_TEMP:?}/lunchlineup-source-${CI_RUN_ID:?}"; build_root="$source_root/build"; temporary="$RUNNER_TEMP/lunchlineup-$kind-$CI_RUN_ID"; output="$artifact_root/$kind"; test ! -e "$temporary"; test ! -e "$output"; mkdir -p "$temporary" "$output"; trap 'rm -rf -- "$temporary"' EXIT
SYFT_IMAGE='anchore/syft:v1.38.0-nonroot@sha256:86e3e28b85481f2a17d6bbc3f436a7d5a1fb4f6e9227ec4c22f70b2e710f7339'; TRIVY_IMAGE='aquasec/trivy:0.69.3@sha256:bcc376de8d77cfe086a917230e818dc9f8528e3c852f7b1aff648949b6258d1c'
node -e 'const x=JSON.parse(require("fs").readFileSync(process.argv[1]));for(const [n,v] of Object.entries(x.images))console.log([n,v.archive.path].join("\t"))' "$manifest" | while IFS=$'\t' read -r name archive_relative; do archive="$artifact_root/$archive_relative"; gzip -dc "$archive" >"$temporary/$name.tar"; if [[ "$kind" == sbom ]]; then docker run --rm --user 0:0 -v "$temporary/$name.tar:/image.tar:ro" -v "$output:/out:rw" "$SYFT_IMAGE" docker-archive:/image.tar -o "spdx-json=/out/$name.spdx.json"; else docker run --rm --user 0:0 -v "$temporary/$name.tar:/image.tar:ro" -v "$build_root/.trivyignore.yaml:/workspace/.trivyignore.yaml:ro" -v "$output:/out:rw" "$TRIVY_IMAGE" image --input /image.tar --format json --output "/out/$name.trivy.json" --scanners vuln --severity HIGH,CRITICAL --ignorefile /workspace/.trivyignore.yaml --exit-code 1; fi; rm -f "$temporary/$name.tar"; done
node "$build_root/scripts/verify-internal-ci-image-reports.mjs" --source-context "$context" --kind "$kind" --release-manifest "$manifest" --report-directory "$output" --scanner-image "$([[ "$kind" == sbom ]] && printf '%s' "$SYFT_IMAGE" || printf '%s' "$TRIVY_IMAGE")" --output "$output/summary.json" --details "$artifact_root/details/$kind.json"
